BUDGET = {"system": 1000, "tools": 2000,
          "retrieved": 6000, "history": 4000, "answer": 2000}

def fit(section, text, counter):
    cap = BUDGET[section]
    if counter(text) <= cap:
        return text
    return truncate_to_tokens(text, cap)  # enforce the cap, protect answer

retrieved = fit("retrieved", rag_snippets(query), count_tokens)
history   = fit("history", conversation_history(), count_tokens)
